+	    } else if (/\s/.test(ch) && depth === 0) {
+	        if (current.length > 0) {
+	            tokens.push(current);
+	            current = '';
+	        }
+	    } else {
+	        current += ch;
+	    }
+	}
+
+	if (current.length > 0) {
+	    tokens.push(current);
+	}
+
+	return tokens.map(part => {
+	    if (part === 'auto') {
+	        return { type: 'auto' };
+	    }
+
+	    const minmaxMatch = part.match(/^minmax\((.+),(.+)\)$/);
+	    if (minmaxMatch) {
+	        const minStr = minmaxMatch[1]!.trim();
+	        const maxStr = minmaxMatch[2]!.trim();
