+	template := e.templateFor(fn)
+	if len(fn.Free) == 0 {
+		if bound, ok := e.bound[template]; ok {
+			return bound
+		}
+		bound := &CompiledFunction{
+			Instructions:  fn.Instructions,
+			NumLocals:     fn.NumLocals,
+			NumParameters: fn.NumParameters,
