+
+import (
+	"strconv"
+	"strings"
+)
+
+type TokenType uint8
+
+const (
+	TokenText TokenType = iota
+	TokenSGR
+	TokenReset
+	TokenHyperlinkOpen
+	TokenHyperlinkClose
+)
+
+type Token struct {
+	Type TokenType
+	Raw  string
+	Text string
+}
+
+func Tokenize(s string) []Token {
+	if s == "" {
+		return nil
+	}
+	var out []Token
+	for i := 0; i < len(s); {
+		if s[i] != '\x1b' {
+			j := i + 1
+			for j < len(s) && s[j] != '\x1b' {
+				j++
+			}
+			text := s[i:j]
+			out = append(out, Token{Type: TokenText, Raw: text, Text: text})
+			i = j
+			continue
+		}
+
+		if i+1 >= len(s) {
+			out = append(out, Token{Type: TokenText, Raw: s[i:], Text: s[i:]})
+			break
+		}
+
+		switch s[i+1] {
+		case '[':
