+					out = append(out, Token{Type: TokenReset, Raw: raw})
+				} else {
+					out = append(out, Token{Type: TokenSGR, Raw: raw})
+				}
+			} else {
+				out = append(out, Token{Type: TokenText, Raw: raw, Text: raw})
+			}
